// Hand-drawn marks. Drawn as single SVG paths with deliberate wobble so they look
// inked by a person, not generated by a shape tool. Used sparingly.

import { clsx } from 'clsx';

export function Underline({ className }: { className?: string }) {
  return (
    <svg className={clsx('pointer-events-none absolute -bottom-2 left-0 h-[12px] w-full overflow-visible', className)} viewBox="0 0 300 12" preserveAspectRatio="none" aria-hidden>
      <path
        className="anim-draw"
        style={{ ['--len' as string]: 330, stroke: 'var(--accent)' }}
        d="M3 8.5c38-3.1 79-5.4 121-5.6 42-.3 88 1.6 130 2.4 14 .2 29 .6 42 .9M28 10.6c52-2.4 118-3.2 166-2.1"
        fill="none"
        strokeWidth="2.4"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Circle({ className }: { className?: string }) {
  return (
    <svg className={clsx('pointer-events-none absolute overflow-visible', className)} viewBox="0 0 200 70" preserveAspectRatio="none" aria-hidden>
      <path
        className="anim-draw"
        style={{ ['--len' as string]: 560, stroke: 'var(--caution)' }}
        d="M112 6C70 3 22 9 9 27c-12 17 20 34 76 37 58 3 104-8 108-27 4-20-36-31-93-31-24 0-46 3-62 8"
        fill="none"
        strokeWidth="2.2"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Arrow({ className, flip }: { className?: string; flip?: boolean }) {
  return (
    <svg className={clsx('pointer-events-none overflow-visible', className)} viewBox="0 0 80 50" aria-hidden style={flip ? { transform: 'scaleX(-1)' } : undefined}>
      <path
        className="anim-draw"
        style={{ ['--len' as string]: 140 }}
        d="M4 6c14 2 32 9 44 21 7 7 11 13 14 19M62 46c-1-6-1-11 1-16M62 46c-5-2-10-3-15-3"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.8"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** Little tick, like a margin check mark. */
export function Tick({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 20 20" aria-hidden fill="none">
      <path d="M3.5 10.8c1.6 1.2 3 2.8 4.1 4.6 2.2-4.6 5.1-8.4 8.9-11.6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

export function Logo({ className }: { className?: string }) {
  // A signal mark: one steady line and one that wavers. Drawn by hand, not a font glyph.
  return (
    <svg className={className} viewBox="0 0 28 28" aria-hidden fill="none">
      <rect x="1.5" y="1.5" width="25" height="25" rx="6" stroke="currentColor" strokeWidth="1.6" />
      <path d="M6 17.5h3.2l2.2-7.3 3.1 11 2.6-7.4 1.4 3.7H22" style={{ stroke: 'var(--accent)' }} strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}
